const state={me:null,config:{},properties:[],products:[],posts:[],roommates:[],socialLinks:[],favoriteIds:[],filters:{q:"",area:"",roomType:"",availability:"",max:"",walk:"",sort:""},authMode:"signin",adminTab:"applications",admin:{overview:null,applications:[],properties:[],products:[],enquiries:[],posts:[],social:[],roommates:[],comments:[]}};
const $=(selector,root=document)=>root.querySelector(selector);const $$=(selector,root=document)=>[...root.querySelectorAll(selector)];
const app=$("#app"),toast=$("#toast"),dialog=$("#dialog"),dialogContent=$("#dialog-content");
const escapeHtml=(value)=>String(value??"").replace(/[&<>"']/g,(c)=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
const money=(value)=>`₦${Number(value||0).toLocaleString("en-NG")}`;
const status=(value,demo=false)=>`<span class="status ${escapeHtml(value)}">${escapeHtml(value)}${demo?" · demo":""}</span>`;
function showToast(message,type=""){toast.textContent=message;toast.className=`toast ${type}`;toast.hidden=false;clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.hidden=true,4200)}
function showDialog(html){dialogContent.innerHTML=html;dialog.showModal()}
$("#dialog-close").onclick=()=>dialog.close();dialog.addEventListener("click",(event)=>{if(event.target===dialog)dialog.close()});
async function api(path,options={}){const response=await fetch(path,{headers:{"content-type":"application/json",...(options.headers||{})},...options});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||"Something went wrong. Try again.");return data}
function route(){return location.hash?location.hash.replace(/^#/ ,""):(location.pathname||"/")}
function setRoute(path){location.hash=path}
function nav(){const actions=$("#topbar-actions");actions.innerHTML=`<button class="button-secondary button-small" id="theme-toggle" type="button">◐ Theme</button>`+(state.me?`<a class="button-secondary button-small" href="#/saved">Saved</a><a class="button-secondary button-small" href="#/profile">Profile</a><button class="button button-small" id="account-button">${escapeHtml(state.me.name.split(" ")[0])}</button>`:`<a class="button-secondary button-small" href="#/signin">Sign in</a><a class="button button-small" href="#/signin?mode=signup">Create account</a>`);$("#account-button")?.addEventListener("click",()=>showAccountMenu());if(state.me?.isAdmin){const link=document.createElement("a");link.href="#/admin";link.className="button-quiet button-small";link.textContent="Admin";actions.prepend(link)}}
function showAccountMenu(){showDialog(`<div class="eyebrow">Your CampusPlug account</div><h2>${escapeHtml(state.me.name)}</h2><p>${escapeHtml(state.me.email)}</p><div class="tag-row">${state.me.roles.map((role)=>`<span class="pill">${escapeHtml(role)}</span>`).join("")}${state.me.isAdmin?'<span class="pill">Admin</span>':''}</div><div class="card-actions" style="margin-top:18px"><a class="button-secondary" href="#/apply/landlord" onclick="dialog.close()">List a property</a><button class="button" id="logout-button">Sign out</button></div>`);$("#logout-button").onclick=async()=>{await api("/api/auth/logout",{method:"POST"});state.me=null;dialog.close();nav();render();showToast("You are signed out.")}}
function legacyShell(){nav();const menu=$("#mobile-menu"),button=$("#menu-button");button.onclick=()=>{const open=!menu.hidden;menu.hidden=open;button.setAttribute("aria-expanded",String(!open))};$$('#mobile-menu a').forEach((link)=>link.onclick=()=>{menu.hidden=true;button.setAttribute("aria-expanded","false")})}
function propertyCard(property,index=0){const saved=state.favoriteIds.includes(property.id);const image=property.images?.[0];const facilities=(property.facilities||[]).slice(0,4);const reviews=Number(property.review_count||0);return `<article class="card"><div class="card-media alt-${index%4+1}">${image?`<img src="${escapeHtml(image.url)}" alt="${escapeHtml(image.alt)}">`:`<div class="media-placeholder"><strong>${escapeHtml(property.area)}</strong><span>Image to be added after approval</span></div>`}</div><div class="card-body"><div class="card-top"><div><div class="eyebrow">${escapeHtml(property.area)} · ${Number(property.walk_minutes||0)} min walk</div><h3 class="card-title">${escapeHtml(property.title)}</h3></div>${status(property.is_demo?"demo":property.verification_status||"unverified",Boolean(property.is_demo))}</div><div class="price">${money(property.price_year)} <small>per year</small></div><div class="meta"><span>${escapeHtml(property.room_type||"Room")}</span><span>·</span><span>${reviews?`★ ${Number(property.average_rating||0).toFixed(1)} (${reviews})`:"No reviews yet"}</span><span>·</span><span>${property.availability_status==="available"?"Available now":"Availability to confirm"}</span><span>·</span><span>${property.owner_name?`Listed by ${escapeHtml(property.owner_name)}`:"CampusPlug sample"}</span></div><div class="tag-row">${facilities.map((tag)=>`<span class="tag">${escapeHtml(tag)}</span>`).join("")}</div>${property.video_url?`<a class="media-link" href="${escapeHtml(property.video_url)}" target="_blank" rel="noopener">▶ Watch lodge video</a>`:""}<div class="card-actions"><button class="button" data-enquire-property="${property.id}">Ask about this place</button><button class="button-quiet" data-save-property="${property.id}" aria-label="${saved?"Remove from saved":"Save"} ${escapeHtml(property.title)}">${saved?"♥ Saved":"♡ Save"}</button></div></div></article>`}
function productCard(product,index=0){const image=product.images?.[0];return `<article class="card market-card"><div class="card-media alt-${(index+1)%4+1}">${image?`<img src="${escapeHtml(image.url)}" alt="${escapeHtml(image.alt)}">`:`<div class="media-placeholder"><strong>${escapeHtml(product.title)}</strong><span>Product image to be added</span></div>`}</div><div class="card-body"><div class="eyebrow">${escapeHtml(product.vendor_name||"Campus vendor")}</div><h3 class="card-title">${escapeHtml(product.title)}</h3><p>${escapeHtml(product.description)}</p><div class="price">${money(product.price)}</div><div class="meta"><span>${product.stock_status==="in_stock"?"In stock":"Stock to confirm"}</span><span>·</span><span>${escapeHtml(product.delivery_info||"Pickup details after enquiry")}</span></div><button class="button" data-enquire-product="${product.id}">Enquire about product</button></div></article>`}
function bindCommon(){ $$('[data-save-property]').forEach((button)=>button.onclick=()=>toggleFavorite(Number(button.dataset.saveProperty)));$$('[data-enquire-property]').forEach((button)=>button.onclick=()=>openEnquiry("property",Number(button.dataset.enquireProperty)));$$('[data-enquire-product]').forEach((button)=>button.onclick=()=>openEnquiry("product",Number(button.dataset.enquireProduct))); }
async function toggleFavorite(id){if(!state.me){setRoute("/signin");showToast("Sign in to save properties.","error");return}try{const saved=state.favoriteIds.includes(id);await api(`/api/favorites/${id}`,{method:saved?"DELETE":"POST"});state.favoriteIds=saved?state.favoriteIds.filter((item)=>item!==id):[...state.favoriteIds,id];render();showToast(saved?"Removed from saved properties.":"Saved to your account.")}catch(error){showToast(error.message,"error")}}
function openEnquiry(kind,id){if(!state.me){setRoute("/signin");showToast("Sign in to send an enquiry.","error");return}const isProperty=kind==="property";const item=(isProperty?state.properties:state.products).find((entry)=>entry.id===id);showDialog(`<div class="eyebrow">${isProperty?"Accommodation enquiry":"Product enquiry"}</div><h2>${escapeHtml(item?.title||"CampusPlug listing")}</h2><p>Send this message to the CampusPlug review inbox. You can follow the status in your account.</p><textarea id="enquiry-message" rows="4" placeholder="What would you like to know?"></textarea><div class="form-actions"><button class="button-secondary" id="cancel-enquiry">Cancel</button><button class="button" id="submit-enquiry">Send enquiry</button></div>`);$("#cancel-enquiry").onclick=()=>dialog.close();$("#submit-enquiry").onclick=async()=>{const message=$("#enquiry-message").value.trim();if(message.length<5)return showToast("Write a little more so the reviewer can help.","error");try{await api("/api/enquiries",{method:"POST",body:JSON.stringify({[isProperty?"propertyId":"productId"]:id,kind:kind,message})});dialog.close();showToast("Enquiry sent. You can track it from your account.","success")}catch(error){showToast(error.message,"error")}}}
async function home(){const q=state.filters;app.innerHTML=`<section class="hero"><div class="eyebrow">UNIZIK, Awka · built for student life</div><h1>Find a place that fits campus life.</h1><p>Search accommodation by area, budget, and walking time. Save your shortlist, ask questions in-site, and move with more confidence.</p><div class="search-panel"><input id="search-input" type="search" value="${escapeHtml(q.q)}" placeholder="Search lodges, areas, or features" aria-label="Search accommodation"><select id="area-select" aria-label="Filter by area"><option value="">Any area</option>${[...new Set(state.properties.map((p)=>p.area))].map((area)=>`<option value="${escapeHtml(area)}" ${q.area===area?"selected":""}>${escapeHtml(area)}</option>`).join("")}</select><select id="room-select" aria-label="Filter by room type"><option value="">Any room type</option><option value="self_contain" ${q.roomType==="self_contain"?"selected":""}>Self contain</option><option value="single_room" ${q.roomType==="single_room"?"selected":""}>Single room</option><option value="shared" ${q.roomType==="shared"?"selected":""}>Shared</option></select><select id="availability-select" aria-label="Filter by availability"><option value="">Any availability</option><option value="available" ${q.availability==="available"?"selected":""}>Available now</option><option value="coming_soon" ${q.availability==="coming_soon"?"selected":""}>Coming soon</option></select><select id="price-select" aria-label="Filter by maximum budget"><option value="">Any budget</option><option value="100000" ${q.max==="100000"?"selected":""}>Up to ₦100,000</option><option value="200000" ${q.max==="200000"?"selected":""}>Up to ₦200,000</option><option value="300000" ${q.max==="300000"?"selected":""}>Up to ₦300,000</option></select><button class="button" id="search-button">Search</button></div></section><section class="info-strip"><div class="info-box"><b>Review before publish</b><p>Applications, listings, and products pass through an admin review queue.</p></div><div class="info-box"><b>Keep your shortlist</b><p>Save properties to your account and compare the details later.</p></div><div class="info-box"><b>Ask in-site</b><p>No forced WhatsApp handoff. Submit questions and follow their status.</p></div></section><section><div class="section-head"><div><div class="eyebrow">Accommodation</div><h2>Places around the gate</h2></div><a class="button-secondary button-small" href="#/apply/landlord">List a property</a></div><div class="filter-row"><button class="filter-chip ${q.walk==="5"?"active":""}" data-walk="5">Within 5 min</button><button class="filter-chip ${q.walk==="10"?"active":""}" data-walk="10">Within 10 min</button><button class="filter-chip ${q.sort==="price"?"active":""}" data-sort="price">Lowest price</button><button class="filter-chip ${q.sort==="far"?"active":""}" data-sort="far">Farthest first</button><button class="filter-chip" id="clear-filters">Clear filters</button></div><div class="grid" id="property-grid">${state.properties.length?state.properties.map(propertyCard).join(""):"<div class=\"empty-state\">No properties match those filters yet. Try a wider budget or check back after the next admin review.</div>"}</div></section><section class="split-section"><div class="panel"><div class="section-head"><div><div class="eyebrow">Campus marketplace</div><h2>Student essentials, in one place.</h2></div><a class="button-secondary button-small" href="#/marketplace">Browse all</a></div><div class="grid">${state.products.slice(0,3).map(productCard).join("")||"<div class=\"empty-state\">Vendor products will appear here after admin approval.</div>"}</div></div><div class="panel soft"><div class="eyebrow">Campus notes</div><h2>Useful before you move.</h2><div class="post-list">${state.posts.slice(0,4).map((post)=>`<article class="post"><h3>${escapeHtml(post.title)}</h3><p>${escapeHtml(post.body)}</p>${post.is_demo?'<span class="status demo">Demo content</span>':''}</article>`).join("")}</div><a class="button" href="#/tools" style="margin-top:12px">Open student tools</a></div></section>`;$("#search-button").onclick=()=>{state.filters={...state.filters,q:$("#search-input").value,area:$("#area-select").value,roomType:$("#room-select").value,availability:$("#availability-select").value,max:$("#price-select").value};refreshProperties()};$("#search-input").onkeydown=(event)=>{if(event.key==="Enter")$("#search-button").click()};$$('[data-walk]').forEach((button)=>button.onclick=()=>{state.filters.walk=state.filters.walk===button.dataset.walk?"":button.dataset.walk;refreshProperties()});$$('[data-sort]').forEach((button)=>button.onclick=()=>{state.filters.sort=state.filters.sort===button.dataset.sort?"":button.dataset.sort;refreshProperties()});$("#clear-filters").onclick=()=>{state.filters={q:"",area:"",roomType:"",availability:"",max:"",walk:"",sort:""};refreshProperties()};bindCommon()}
async function refreshProperties(){const q=new URLSearchParams(Object.entries(state.filters).filter(([,value])=>value));const data=await api(`/api/properties?${q}`);state.properties=data.properties;state.favoriteIds=data.favoriteIds;render()}
function signin(){const signup=location.hash.includes("mode=signup");if(signup)state.authMode="signup";app.innerHTML=`<section class="auth-shell"><div class="auth-card panel"><div class="eyebrow">Your campus, connected</div><h1 style="font-size:2.4rem">${state.authMode==="signup"?"Create your CampusPlug account.":"Welcome back to CampusPlug."}</h1><p>${state.authMode==="signup"?"One account for accommodation, campus tools, and partner applications.":"Sign in to manage your shortlist, enquiries, and partner workspace."}</p><div class="auth-switch"><button class="${state.authMode==="signin"?"active":""}" data-auth-mode="signin">Sign in</button><button class="${state.authMode==="signup"?"active":""}" data-auth-mode="signup">Create account</button></div><button class="google-button" id="google-button">Continue with Google</button><div id="google-note" class="notice hidden"></div><div class="divider">or use email</div><form id="auth-form" class="form-grid"><div class="field-group full ${state.authMode==="signin"?"hidden":""}"><label for="auth-name">Full name</label><input id="auth-name" autocomplete="name" placeholder="Your full name"></div><div class="field-group full"><label for="auth-email">Email address</label><input id="auth-email" type="email" autocomplete="email" placeholder="you@example.com" required></div><div class="field-group full"><label for="auth-password">Password</label><input id="auth-password" type="password" autocomplete="${state.authMode==="signin"?"current-password":"new-password"}" placeholder="At least 8 characters" required></div><div class="field-group full ${state.authMode==="signin"?"hidden":""}"><label for="auth-phone">Phone number <span class="muted">(optional)</span></label><input id="auth-phone" type="tel" autocomplete="tel" placeholder="08012345678"></div><div class="field-group full ${state.authMode==="signin"?"hidden":""}"><label>What else describes you?</label><div class="choice-row"><label class="choice"><input type="checkbox" name="role" value="Landlord / agent"> Landlord / agent</label><label class="choice"><input type="checkbox" name="role" value="Vendor"> Vendor</label></div><small>Student is included automatically. Extra roles go through admin review.</small></div><div class="field-group full ${state.authMode==="signin"?"hidden":""}"><label class="choice"><input type="checkbox" id="auth-terms"> I agree to the CampusPlug terms and privacy notice.</label></div><div class="field-group full"><button class="button" type="submit">${state.authMode==="signup"?"Create account":"Sign in"}</button></div><div id="auth-message" class="field-group full"></div></form><p class="muted" style="font-size:.8rem;margin-top:16px">CampusPlug will never ask for your password, PIN, or card details through a chat message.</p></div></section>`;$$('[data-auth-mode]').forEach((button)=>button.onclick=()=>{state.authMode=button.dataset.authMode;render()});$("#google-button").onclick=async()=>{try{const data=await api(`/api/auth/google/start?origin=${encodeURIComponent(location.origin)}`);location.href=data.url}catch(error){$("#google-note").className="notice";$("#google-note").textContent=error.message;$("#google-note").classList.remove("hidden")}};$("#auth-form").onsubmit=async(event)=>{event.preventDefault();const message=$("#auth-message"),roles=$$("input[name=role]:checked").map((input)=>input.value);if(state.authMode==="signup"&&!$("#auth-terms").checked){message.innerHTML='<div class="notice error">Accept the terms and privacy notice to continue.</div>';return}try{const data=await api(`/api/auth/${state.authMode}`,{method:"POST",body:JSON.stringify({name:$("#auth-name")?.value,email:$("#auth-email").value,password:$("#auth-password").value,phone:$("#auth-phone")?.value,roles})});state.me=data.user;await loadData();setRoute("/");showToast(data.message||"You are signed in.","success")}catch(error){message.innerHTML=`<div class="notice error">${escapeHtml(error.message)}</div>`}}}
function applyPage(role){const vendor=role==="vendor";const heading=vendor?"Become a CampusPlug vendor":"List accommodation on CampusPlug";const intro=vendor?"Tell us about your business. An admin reviews your application before you can add products.":"Apply to become a CampusPlug accommodation partner. Admin approval is required before properties go live.";if(!state.me){app.innerHTML=`<section class="form-shell"><div class="panel"><div class="eyebrow">Partner onboarding</div><h1>${heading}.</h1><p>${intro}</p><a class="button" href="#/signin?mode=signup">Create an account first</a><a class="button-secondary" href="#/signin" style="margin-left:8px">Sign in</a></div></section>`;return}app.innerHTML=`<section class="form-shell"><div class="form-header"><div class="eyebrow">Partner onboarding</div><h1>${heading}.</h1><p>${intro}</p></div><form class="panel form-grid" id="partner-form">${vendor?'<div class="field-group"><label for="businessName">Business name</label><input id="businessName" required placeholder="e.g. Campus Styles"></div><div class="field-group"><label for="category">Category</label><select id="category"><option>Cosmetics and beauty</option><option>Phones and accessories</option><option>Laptops and accessories</option><option>Food and snacks</option><option>Fashion</option><option>Books and school supplies</option><option>Other</option></select></div>':'<div class="field-group"><label for="nameOrAgency">Name or agency</label><input id="nameOrAgency" required placeholder="Your name or agency name"></div><div class="field-group"><label for="areas">Areas covered</label><input id="areas" required placeholder="Ifite, Amansea, Aroma"></div>'}<div class="field-group"><label for="phone">Phone number</label><input id="phone" required value="${escapeHtml(state.me.phone||"")}" placeholder="08012345678"></div><div class="field-group"><label for="location">${vendor?"Business location":"Preferred contact location"}</label><input id="location" required placeholder="Area, shop, or pickup location"></div>${vendor?"":'<div class="field-group full"><label for="videoUrl">Lodge video link <span class="muted">(optional)</span></label><input id="videoUrl" type="url" placeholder="https://youtu.be/... or a hosted video URL"></div>'}<div class="field-group full"><label for="details">${vendor?"What you sell and how students buy":"Property types, rent range, and what students should know"}</label><textarea id="details" required rows="5" placeholder="Add the details an admin should review."></textarea></div><div class="field-group full"><div id="partner-message"></div><div class="form-actions"><a class="button-secondary" href="#/">Cancel</a><button class="button" type="submit">Submit for admin review</button></div></div></form></section>`;$("#partner-form").onsubmit=async(event)=>{event.preventDefault();const body=vendor?{businessName:$("#businessName").value,category:$("#category").value,phone:$("#phone").value,location:$("#location").value,details:$("#details").value}:{nameOrAgency:$("#nameOrAgency").value,areas:$("#areas").value,phone:$("#phone").value,location:$("#location").value,videoUrl:$("#videoUrl")?.value,details:$("#details").value};try{const data=await api(`/api/applications/${role}`,{method:"POST",body:JSON.stringify(body)});$("#partner-message").innerHTML=`<div class="notice success">${escapeHtml(data.message)}</div>`;event.target.reset()}catch(error){$("#partner-message").innerHTML=`<div class="notice error">${escapeHtml(error.message)}</div>`}}}
async function sellPage(){if(!state.me){app.innerHTML=`<section class="form-shell"><div class="panel"><div class="eyebrow">Vendor workspace</div><h1>List a product after approval.</h1><p>Sign in and apply as a vendor first. Once an admin approves you, this form unlocks for product submissions.</p><a class="button" href="#/signin?mode=signup">Create account</a></div></section>`;return}if(!state.me.roles.includes("Vendor")&&!state.me.isAdmin){app.innerHTML=`<section class="form-shell"><div class="panel"><div class="eyebrow">Vendor workspace</div><h1>Your shop starts with a review.</h1><p>Submit a vendor application first. The product form appears after admin approval.</p><a class="button" href="#/apply/vendor">Apply as a vendor</a></div></section>`;return}app.innerHTML=`<section class="form-shell"><div class="form-header"><div class="eyebrow">Vendor workspace</div><h1>Add a product.</h1><p>New products stay pending until an admin approves them.</p></div><form class="panel form-grid" id="product-form"><div class="field-group"><label for="product-title">Product name</label><input id="product-title" required placeholder="e.g. Fast charger"></div><div class="field-group"><label for="product-price">Price (₦)</label><input id="product-price" type="number" min="1" required placeholder="6000"></div><div class="field-group"><label for="product-stock">Stock</label><select id="product-stock"><option value="in_stock">In stock</option><option value="low_stock">Low stock</option><option value="out_of_stock">Out of stock</option></select></div><div class="field-group"><label for="product-delivery">Delivery / pickup</label><input id="product-delivery" placeholder="Delivery to hostel or pickup point"></div><div class="field-group full"><label for="product-description">Description</label><textarea id="product-description" required rows="4" placeholder="What students should know before ordering"></textarea></div><div class="field-group full"><label for="product-images">Product images <span class="muted">(optional, up to 8 MB each)</span></label><input id="product-images" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></div><div class="field-group full"><div id="product-message"></div><div class="form-actions"><button class="button" type="submit">Submit product for review</button></div></div></form></section>`;$("#product-form").onsubmit=async(event)=>{event.preventDefault();try{const images=await uploadSelectedImages($("#product-images").files,"product");const data=await api("/api/products",{method:"POST",body:JSON.stringify({title:$("#product-title").value,price:$("#product-price").value,stockStatus:$("#product-stock").value,deliveryInfo:$("#product-delivery").value,description:$("#product-description").value,images})});$("#product-message").innerHTML=`<div class="notice success">${escapeHtml(data.message)}</div>`;event.target.reset()}catch(error){$("#product-message").innerHTML=`<div class="notice error">${escapeHtml(error.message)}</div>`}}}
async function uploadSelectedImages(files,kind){const output=[];for(const file of [...files].slice(0,6)){const signed=await api("/api/uploads/presign",{method:"POST",body:JSON.stringify({mime:file.type,size:file.size,kind})});const response=await fetch(signed.uploadUrl,{method:"PUT",headers:{"content-type":file.type},body:file});if(!response.ok)throw new Error("One of the image uploads failed.");output.push({key:signed.key,url:signed.url,alt:file.name})}return output}
function marketplace(){app.innerHTML=`<section class="hero"><div class="eyebrow">Campus marketplace</div><h1>Student essentials without the runaround.</h1><p>Browse products from approved campus vendors. Orders begin with an in-site enquiry, so your details stay in your account while the marketplace grows.</p><a class="button" href="#/apply/vendor">Become a vendor</a></section><div class="section-head"><div><div class="eyebrow">Approved products</div><h2>What is available now</h2></div><a class="button-secondary button-small" href="#/sell">List a product</a></div><div class="grid">${state.products.length?state.products.map(productCard).join(""):"<div class=\"empty-state\">No approved products yet. Vendor applications are reviewed before anything goes live.</div>"}</div>`;bindCommon()}
async function saved(){if(!state.me){setRoute("/signin");return}const data=await api("/api/saved");app.innerHTML=`<section class="section-head" style="margin-top:34px"><div><div class="eyebrow">Your shortlist</div><h1 style="font-size:3rem">Saved properties.</h1><p>Keep the places you want to inspect together.</p></div><a class="button-secondary" href="#/">Browse more</a></section><div class="grid">${data.properties.length?data.properties.map(propertyCard).join(""):"<div class=\"empty-state\">No saved properties yet. Tap Save on a property to build your shortlist.</div>"}</div>`;bindCommon()}
function legacyTools(){app.innerHTML=`<section class="hero"><div class="eyebrow">Student tools</div><h1>Small tools for big campus days.</h1><p>Keep your planning in one calm place while you search, compare, and prepare.</p></section><div class="grid"><article class="panel grid-wide"><div class="eyebrow">Safety first</div><h2>Lodge viewing checklist</h2><p>Use this before any payment: confirm water, light and meter access; test locks, roof, toilet and bathroom; check noise and the walk home; agree fees and rules in writing; ask for a receipt.</p><div class="tag-row"><span class="tag">Water</span><span class="tag">Light</span><span class="tag">Locks</span><span class="tag">Written terms</span><span class="tag">Receipt</span></div></article><article class="panel"><div class="eyebrow">CGPA calculator</div><h2>Plan your next semester</h2><p>Use the 5-point scale. Add credit units and grades below.</p><div id="cgpa-rows"></div><button class="button-secondary button-small" id="add-course">Add course</button><div class="price" id="cgpa-output" style="margin-top:14px">Add courses to calculate</div></article><article class="panel"><div class="eyebrow">Exam countdown</div><h2>Keep dates visible</h2><p>Add a course and date to keep your next deadline close.</p><form id="exam-form" class="field-group"><input id="exam-name" placeholder="Course, e.g. MTH 101"><input id="exam-date" type="date"><button class="button" type="submit">Add exam</button></form><div id="exam-list" class="post-list" style="margin-top:14px"></div></article></div>`;setupCgpa();setupExams()}
function setupCgpa(){const rows=$("#cgpa-rows");const add=()=>{const row=document.createElement("div");row.className="form-grid";row.style.marginBottom="8px";row.innerHTML='<input placeholder="Course" aria-label="Course"><input class="units" type="number" min="1" placeholder="Units" aria-label="Credit units"><select class="grade" aria-label="Grade"><option value="">Grade</option><option value="5">A</option><option value="4">B</option><option value="3">C</option><option value="2">D</option><option value="1">E</option><option value="0">F</option></select>';rows.appendChild(row);$$('input,select',row).forEach((input)=>input.oninput=calculate)};const calculate=()=>{let points=0,units=0;$$('.form-grid',rows).forEach((row)=>{const u=Number($('.units',row)?.value),g=$('.grade',row)?.value;if(u&&g!==""){units+=u;points+=u*Number(g)}});$("#cgpa-output").innerHTML=units?`${(points/units).toFixed(2)} <small>semester GPA</small>`:"Add courses to calculate"};for(let i=0;i<3;i++)add();$("#add-course").onclick=add}
function setupExams(){const key="campusplug_exams";const read=()=>{try{return JSON.parse(localStorage.getItem(key)||"[]")}catch{return[]}};const draw=()=>{$("#exam-list").innerHTML=read().sort((a,b)=>a.date.localeCompare(b.date)).map((exam,index)=>{const days=Math.ceil((new Date(`${exam.date}T00:00:00`)-new Date())/86400000);return `<div class="post"><div style="display:flex;justify-content:space-between;gap:10px"><b>${escapeHtml(exam.name)}</b><span class="pill">${days<0?"Done":days===0?"Today":`${days} days`}</span></div><small>${escapeHtml(exam.date)}</small><button class="button-quiet button-small" data-remove-exam="${index}">Remove</button></div>`}).join("")||'<p class="muted">No exam dates saved on this device yet.</p>';$$('[data-remove-exam]').forEach((button)=>button.onclick=()=>{const all=read();all.splice(Number(button.dataset.removeExam),1);localStorage.setItem(key,JSON.stringify(all));draw()})};$("#exam-form").onsubmit=(event)=>{event.preventDefault();const name=$("#exam-name").value.trim(),date=$("#exam-date").value;if(!name||!date)return;const all=read();all.push({name,date});localStorage.setItem(key,JSON.stringify(all));event.target.reset();draw()};draw()}
async function loadAdmin(){const [overview,applications,properties,products,enquiries,posts,comments,social,roommates,reviews]=await Promise.all([api('/api/admin/overview'),api('/api/admin/applications'),api('/api/admin/properties'),api('/api/admin/products'),api('/api/admin/enquiries'),api('/api/admin/posts'),api('/api/admin/comments'),api('/api/admin/social'),api('/api/admin/roommates'),api('/api/admin/reviews')]);state.admin={overview,applications:applications.applications,properties:properties.properties,products:products.products,enquiries:enquiries.enquiries,posts:posts.posts,comments:comments.comments,social:social.links||[],roommates:roommates.listings||[],reviews:reviews.reviews||[]}}
function bindAdminActions(){
  $$('[data-approve-application]').forEach(b=>b.onclick=()=>moderateApplication(b.dataset.approveApplication,'approved'));$$('[data-reject-application]').forEach(b=>b.onclick=()=>moderateApplication(b.dataset.rejectApplication,'rejected'));$$('[data-approve-listing]').forEach(b=>b.onclick=()=>moderateListing(b.dataset.approveListing,'approved',true));$$('[data-hide-listing]').forEach(b=>b.onclick=()=>moderateListing(b.dataset.hideListing,'hidden',false));$$('[data-edit-listing]').forEach(b=>b.onclick=()=>editListing(b.dataset.editListing));$('#new-admin-property')?.addEventListener('click',()=>showAdminCreate('property'));$('#new-admin-product')?.addEventListener('click',()=>showAdminCreate('product'));
  $('#new-admin-post')?.addEventListener('click',()=>{showDialog(`<div class="eyebrow">Admin publishing</div><h2>New campus update</h2><form id="post-admin-form" class="form-grid"><div class="field-group full"><label>Headline</label><input id="post-title" required></div><div class="field-group"><label>Type</label><select id="post-type"><option value="news">News</option><option value="opportunity">Opportunity</option><option value="safety">Safety</option><option value="area_update">Area update</option></select></div><div class="field-group full"><label>Optional image <span class="muted">(JPG/PNG/WebP/GIF up to 8 MB)</span></label><input id="post-image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"><label>Update</label><textarea id="post-body" rows="5" required></textarea></div><button class="button full">Publish update</button></form>`);$('#post-admin-form').onsubmit=async e=>{e.preventDefault();const images=await uploadSelectedImages($('#post-image').files,'post');await api('/api/admin/posts',{method:'POST',body:JSON.stringify({title:$('#post-title').value,postType:$('#post-type').value,body:$('#post-body').value,imageUrl:images[0]?.url})});dialog.close();await loadAdmin();render()}});
  $('[data-hide-post]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/posts/${b.dataset.hidePost}`,{method:'PATCH',body:JSON.stringify({status:'hidden'})});await loadAdmin();render()});$('[data-approve-roommate]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/roommates/${b.dataset.approveRoommate}`,{method:'PATCH',body:JSON.stringify({status:'approved'})});await loadAdmin();render()});$('[data-reject-roommate]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/roommates/${b.dataset.rejectRoommate}`,{method:'PATCH',body:JSON.stringify({status:'rejected'})});await loadAdmin();render()});
  $('[data-approve-review]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/reviews/${b.dataset.approveReview}`,{method:'PATCH',body:JSON.stringify({status:'published'})});await loadAdmin();render()});$('[data-hide-review]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/reviews/${b.dataset.hideReview}`,{method:'PATCH',body:JSON.stringify({status:'hidden'})});await loadAdmin();render()});
  $('[data-hide-comment]').forEach(b=>b.onclick=async()=>{await api(`/api/admin/comments/${b.dataset.hideComment}`,{method:'PATCH',body:JSON.stringify({status:'hidden'})});await loadAdmin();render()});
  $('#social-admin-form')?.addEventListener('submit',async e=>{e.preventDefault();const links=[...(state.admin.social||[]),{name:$('#social-name').value,url:$('#social-url').value,description:$('#social-description').value}];await api('/api/admin/social',{method:'PUT',body:JSON.stringify({links})});await loadAdmin();render()});$('[data-remove-social]').forEach(b=>b.onclick=async()=>{const links=(state.admin.social||[]).filter((_,i)=>i!==Number(b.dataset.removeSocial));await api('/api/admin/social',{method:'PUT',body:JSON.stringify({links})});await loadAdmin();render()})}
async function moderateApplication(id,next){try{await api(`/api/admin/applications/${id}`,{method:"PATCH",body:JSON.stringify({status:next})});await loadAdmin();render();showToast(`Application ${next}.`,"success")}catch(error){showToast(error.message,"error")}}
async function moderateListing(key,next,publish){const [type,id]=key.split(":");try{await api(`/api/admin/${type==='property'?"properties":"products"}/${id}`,{method:"PATCH",body:JSON.stringify({status:next,published:publish,verificationStatus:publish?"verified":"unverified"})});await loadAdmin();render();showToast(`Record ${next}.`,"success")}catch(error){showToast(error.message,"error")}}
function editListing(key){const [type,id]=key.split(":");const item=(type==="property"?state.admin.properties:state.admin.products).find((entry)=>String(entry.id)===id);if(!item)return;showDialog(`<div class="eyebrow">Admin edit</div><h2>Edit ${type}</h2><form id="edit-record" class="form-grid"><div class="field-group full"><label for="edit-title">Title</label><input id="edit-title" value="${escapeHtml(item.title)}"></div><div class="field-group full"><label for="edit-description">Description</label><textarea id="edit-description" rows="4">${escapeHtml(item.description)}</textarea></div><div class="field-group"><label for="edit-price">${type==="property"?"Yearly price":"Price"}</label><input id="edit-price" type="number" value="${type==="property"?item.price_year:item.price}"></div><div class="field-group"><label for="edit-note">Admin note</label><input id="edit-note" placeholder="Optional review note"></div><div class="field-group full"><button class="button" type="submit">Save edits</button></div></form>`);$("#edit-record").onsubmit=async(event)=>{event.preventDefault();try{await api(`/api/admin/${type==='property'?"properties":"products"}/${id}`,{method:"PATCH",body:JSON.stringify({status:item.status,published:Boolean(item.published),title:$("#edit-title").value,description:$("#edit-description").value,[type==="property"?"priceYear":"price"]:$("#edit-price").value,note:$("#edit-note").value})});dialog.close();await loadAdmin();render();showToast("Edits saved.","success")}catch(error){showToast(error.message,"error")}}}
function showAdminCreate(type){const property=type==='property';showDialog(`<div class="eyebrow">Admin publishing</div><h2>Add ${property?'a property':'a product'}</h2><form id="admin-create" class="form-grid"><div class="field-group full"><label for="create-title">Title</label><input id="create-title" required placeholder="${property?'Self-contain near Ifite':'Product name'}"></div><div class="field-group"><label for="create-price">${property?'Yearly price':'Price'}</label><input id="create-price" type="number" min="1" required></div>${property?`<div class="field-group"><label for="create-area">Area</label><input id="create-area" required placeholder="Ifite"></div><div class="field-group"><label for="create-walk">Walking time</label><input id="create-walk" type="number" min="0" placeholder="Minutes"></div><div class="field-group"><label for="create-availability">Availability</label><select id="create-availability"><option value="available">Available now</option><option value="taken">Taken</option><option value="coming_soon">Coming soon</option></select></div><div class="field-group full"><label for="create-facilities">Facilities</label><input id="create-facilities" placeholder="Water, fenced, prepaid meter"></div><div class="field-group full"><label for="create-video">Lodge video link <span class="muted">(optional)</span></label><input id="create-video" type="url" placeholder="https://youtu.be/... or hosted video URL"></div>`:`<div class="field-group"><label for="create-delivery">Delivery / pickup</label><input id="create-delivery"></div>`}<div class="field-group full"><label for="create-description">Description</label><textarea id="create-description" required rows="4"></textarea></div><div class="field-group full"><button class="button" type="submit">Publish now</button></div></form>`);$('#admin-create').onsubmit=async event=>{event.preventDefault();try{const payload=property?{title:$('#create-title').value,priceYear:$('#create-price').value,area:$('#create-area').value,walkMinutes:$('#create-walk').value,availabilityStatus:$('#create-availability').value,facilities:$('#create-facilities').value.split(',').map(x=>x.trim()),videoUrl:$('#create-video').value,description:$('#create-description').value}:{title:$('#create-title').value,price:$('#create-price').value,deliveryInfo:$('#create-delivery').value,description:$('#create-description').value};await api(`/api/admin/${property?'properties':'products'}`,{method:'POST',body:JSON.stringify(payload)});dialog.close();await loadAdmin();render();showToast('Published from admin.','success')}catch(error){showToast(error.message,'error')}}}
async function legacyLoadData(){const [me,config,properties,products,posts]=await Promise.all([api("/api/me"),api("/api/config"),api("/api/properties"),api("/api/products"),api("/api/posts")]);state.me=me.user;state.config=config;state.properties=properties.properties;state.favoriteIds=properties.favoriteIds;state.products=products.products;state.posts=posts.posts}
async function legacyRender(){shell();const current=route();if(current.startsWith("/signin"))signin();else if(current==="/profile")await profile();else if(current==="/marketplace")marketplace();else if(current==="/saved")await saved();else if(current==="/tools")tools();else if(current==="/admin")await admin();else if(current==="/apply/vendor")applyPage("vendor");else if(current==="/apply/landlord")applyPage("landlord");else if(current==="/sell")await sellPage();else await home();app.focus()}

function applyTheme(){const saved=localStorage.getItem("campusplug_theme")||"light";document.documentElement.dataset.theme=saved;const button=$("#theme-toggle");if(button){button.textContent=saved==="dark"?"☀ Light":"◐ Theme";button.onclick=()=>{const next=document.documentElement.dataset.theme==="dark"?"light":"dark";document.documentElement.dataset.theme=next;localStorage.setItem("campusplug_theme",next);button.textContent=next==="dark"?"☀ Light":"◐ Theme"}}}
function shell(){nav();const menu=$("#mobile-menu"),button=$("#menu-button");if(button)button.onclick=()=>{const open=!menu.hidden;menu.hidden=open;button.setAttribute("aria-expanded",String(!open))};$$('#mobile-menu a').forEach((link)=>link.onclick=()=>{menu.hidden=true;button.setAttribute("aria-expanded","false")});applyTheme()}
function themeTools(){return `<div class="panel soft"><div class="eyebrow">Make CampusPlug yours</div><h2>Choose your view</h2><p>Switch between a bright day view and a calmer night view whenever you study late.</p><button class="button-secondary" id="theme-toggle-inline">Toggle light / dark theme</button></div>`}
function tools(){app.innerHTML=`<section class="hero"><div class="eyebrow">Student tools</div><h1>Small tools for big campus days.</h1><p>Useful shortcuts for the moments students actually face: moving, budgeting, studying, staying safe, and finding help.</p></section><div class="grid"><article class="panel grid-wide"><div class="eyebrow">Before you pay</div><h2>Lodge viewing checklist</h2><p>Confirm water, light, meter access, locks, roof, bathroom, noise, written fees, house rules, receipt, and your route home.</p><div class="tag-row"><span class="tag">Water</span><span class="tag">Light</span><span class="tag">Locks</span><span class="tag">Written terms</span><span class="tag">Receipt</span></div></article><article class="panel"><div class="eyebrow">Weekly budget planner</div><h2>Know what you can spend.</h2><p>Set your weekly money and see a simple daily guide.</p><form id="budget-form" class="field-group"><input id="budget-total" type="number" min="0" placeholder="Weekly budget, ₦"><input id="budget-days" type="number" min="1" max="14" value="7" placeholder="Days"><button class="button" type="submit">Calculate</button></form><div class="price" id="budget-output" style="margin-top:14px">Add your budget</div></article><article class="panel"><div class="eyebrow">Exam countdown</div><h2>Keep deadlines visible.</h2><p>Add a course and date for a quick reminder list.</p><form id="exam-form" class="field-group"><input id="exam-name" placeholder="Course, e.g. MTH 101"><input id="exam-date" type="date"><button class="button" type="submit">Add exam</button></form><div id="exam-list" class="post-list" style="margin-top:14px"></div></article><article class="panel"><div class="eyebrow">Safety contacts</div><h2>Save help before you need it.</h2><p>Keep your department office, trusted family contact, landlord contact, campus security, and nearest clinic in your phone.</p><button class="button-secondary" id="copy-safety">Copy a safety checklist</button></article><article class="panel">${themeTools()}</article></div>`;setupExams();$("#budget-form").onsubmit=e=>{e.preventDefault();const total=Number($("#budget-total").value),days=Number($("#budget-days").value)||7;$("#budget-output").innerHTML=total?`${money(total/days)} <small>per day guide</small>`:"Add your budget"};$("#copy-safety").onclick=async()=>{await navigator.clipboard?.writeText("Campus safety contacts: family · department · campus security · nearest clinic · trusted landlord");showToast("Safety checklist copied.","success")};$("#theme-toggle-inline").onclick=()=>{$("#theme-toggle")?.click()}}
function newsCard(post){return `<article class="post news-card" data-post="${post.id}">${post.image_url?`<div class="news-image"><img src="${escapeHtml(post.image_url)}" alt="${escapeHtml(post.title)}" loading="lazy"></div>`:""}<div class="eyebrow">${escapeHtml(post.post_type||"update")}${post.is_demo?" · demo":""}</div><h2>${escapeHtml(post.title)}</h2><p>${escapeHtml(post.body)}</p><div class="news-meta"><span>By ${escapeHtml(post.author_name||"CampusPlug")}</span><span>${escapeHtml(post.created_at||"")}</span></div><div class="news-actions"><button class="button-quiet button-small" data-like-post="${post.id}">${post.liked?"♥ Liked":"♡ Like"} · ${post.like_count||0}</button><button class="button-quiet button-small" data-comments-post="${post.id}">Comments · ${post.comment_count||0}</button><button class="button-quiet button-small share-button" data-share-post="${post.id}" data-share-title="${escapeHtml(post.title)}">↗ Share</button></div><div class="comments-panel" id="comments-${post.id}" hidden></div></article>`}
async function loadComments(postId){const panel=$(`#comments-${postId}`);if(!panel)return;const data=await api(`/api/posts/${postId}/comments`);panel.hidden=false;panel.innerHTML=`<div class="comment-list">${data.comments.map(comment=>`<div class="comment"><b>${escapeHtml(comment.author_name)}</b><p>${escapeHtml(comment.body)}</p></div>`).join("")||'<p class="muted">No comments yet. Start the conversation.</p>'}</div>${state.me?`<form class="comment-form" data-comment-form="${postId}"><input name="body" placeholder="Add a respectful comment" required><button class="button-small button" type="submit">Post</button></form>`:'<p class="muted"><a href="#/signin">Sign in</a> to comment.</p>'}`;panel.querySelector('form')?.addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/posts/${postId}/comments`,{method:'POST',body:JSON.stringify({body:e.target.body.value})});await loadData();news()}catch(error){showToast(error.message,'error')}})}
function bindNews(){ $$('[data-like-post]').forEach(button=>button.onclick=async()=>{if(!state.me){setRoute('/signin');showToast('Sign in to like a post.','error');return}try{await api(`/api/posts/${button.dataset.likePost}/like`,{method:'POST'});await loadData();news()}catch(error){showToast(error.message,'error')}});$$('[data-comments-post]').forEach(button=>button.onclick=()=>loadComments(button.dataset.commentsPost));$$('[data-share-post]').forEach(button=>button.onclick=async()=>{const url=`${location.origin}${location.pathname}#/news?post=${button.dataset.sharePost}`,title=button.dataset.shareTitle||'CampusPlug campus news';try{if(navigator.share){await navigator.share({title,text:`${title} — CampusPlug`,url})}else{await navigator.clipboard.writeText(url);showToast('News link copied.','success')}}catch(error){if(error.name!=='AbortError'){try{await navigator.clipboard.writeText(url);showToast('News link copied.','success')}catch{showToast('Copy the page URL to share this news.','error')}}}});$$('[data-news-form]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{const images=await uploadSelectedImages(form.querySelector("#news-image")?.files||[] ,"post");const data=await api('/api/posts',{method:'POST',body:JSON.stringify({title:form.title.value,postType:form.postType.value,body:form.body.value,imageUrl:images[0]?.url})});form.reset();showToast(data.message,'success')}catch(error){showToast(error.message,'error')}})}
function news(){app.innerHTML=`<section class="news-page"><section class="news-hero form-header"><div class="eyebrow">Campus news & updates</div><h1>Know what is happening around campus.</h1><p>School resumption, safety information, area alerts, opportunities, and useful student updates in one place.</p></section>${state.me?`<section class="panel news-submit"><div class="eyebrow">Have useful information?</div><h2>Share an update with students.</h2><p>Students can submit updates. CampusPlug reviews them before publication so the feed stays trustworthy.</p><form class="form-grid" data-news-form><div class="field-group"><label for="news-title">Headline</label><input id="news-title" name="title" required placeholder="e.g. School resumes on Monday"></div><div class="field-group"><label for="news-type">Type</label><select id="news-type" name="postType"><option value="community">Community update</option><option value="resumption">Resumption</option><option value="security">Security</option><option value="area_update">Area update</option><option value="opportunity">Opportunity</option></select></div><div class="field-group full"><label for="news-image">Image <span class="muted">(optional, JPG/PNG/WebP/GIF up to 8 MB)</span></label><input id="news-image" type="file" accept="image/png,image/jpeg,image/webp,image/gif"></div><div class="field-group full"><label for="news-body">What should students know?</label><textarea id="news-body" name="body" required rows="5" placeholder="Share clear, useful details and where students can verify them."></textarea></div><button class="button full" type="submit">Submit update for review</button></form></section>`:'<section class="panel news-submit"><h2>Have useful campus information?</h2><p>Sign in to submit school, safety, and area updates for review.</p><a class="button" href="#/signin">Sign in to post</a></section>'}<div class="post-list">${state.posts.map(newsCard).join("")||'<div class="empty-state">No updates yet. Check back soon.</div>'}</div></section></section>`;bindNews();const postId=new URLSearchParams(location.hash.split("?")[1]||"").get("post");if(postId)setTimeout(()=>document.querySelector(`[data-post="${postId}"]`)?.scrollIntoView({behavior:"smooth",block:"start"}),0)}
function social(){app.innerHTML=`<section class="hero"><div class="eyebrow">CampusPlug social</div><h1>Stay plugged into student life.</h1><p>Follow the channels you trust for announcements, deals, student stories, and community updates.</p></section><section class="grid">${state.socialLinks.length?state.socialLinks.map(link=>`<article class="panel social-card"><div class="eyebrow">${escapeHtml(link.name)}</div><h2>${escapeHtml(link.name)}</h2><p>${escapeHtml(link.description||"Official CampusPlug social channel")}</p><a class="button" href="${escapeHtml(link.url)}" target="_blank" rel="noopener">Open channel</a></article>`).join(""):'<div class="empty-state">Social links will appear here after the admin adds them.</div>'}</section>`}
function roommateCard(item){return `<article class="card"><div class="card-body"><div class="eyebrow">${escapeHtml(item.area)} · ${money(item.budget)} budget</div><h2>${escapeHtml(item.title)}</h2><p>${escapeHtml(item.bio)}</p><div class="tag-row"><span class="tag">Looking for: ${escapeHtml(item.looking_for)}</span>${item.move_in_date?`<span class="tag">From ${escapeHtml(item.move_in_date)}</span>`:""}</div><div class="meta">Posted by ${escapeHtml(item.user_name||"Campus student")}</div><button class="button" data-roommate-contact="${item.id}">Introduce yourself</button></div></article>`}
async function roommates(){const data=await api("/api/roommates");state.roommates=data.listings;app.innerHTML=`<section class="form-header"><div class="eyebrow">Roommates</div><h1>Find a better room match.</h1><p>List the kind of room or person you need. Profiles stay pending until an admin reviews them.</p><div class="card-actions"><a class="button" href="#/roommates/new">List your room need</a><a class="button-secondary" href="#/news">Campus updates</a></div></section><div class="grid">${state.roommates.map(roommateCard).join("")||'<div class="empty-state">No approved roommate profiles yet.</div>'}</div>`;$$('[data-roommate-contact]').forEach(b=>b.onclick=()=>{if(!state.me){setRoute("/signin");showToast("Sign in to contact a roommate.","error");return}showDialog(`<div class="eyebrow">Roommate introduction</div><h2>Say hello</h2><p>Keep it respectful. Do not send passwords, PINs, or payment details.</p><textarea id="roommate-message" rows="5" placeholder="Hi, I saw your profile and... "></textarea><div class="form-actions"><button class="button" id="send-roommate">Send introduction</button></div>`);$("#send-roommate").onclick=async()=>{try{await api(`/api/roommates/${b.dataset.roommateContact}/requests`,{method:"POST",body:JSON.stringify({message:$("#roommate-message").value})});dialog.close();showToast("Introduction sent.","success")}catch(e){showToast(e.message,"error")}}})}
function newRoommate(){if(!state.me){setRoute("/signin");return}app.innerHTML=`<section class="form-shell"><div class="form-header"><div class="eyebrow">Roommate listing</div><h1>Tell students what you need.</h1><p>Your profile will be reviewed before it appears publicly.</p></div><form class="panel form-grid" id="roommate-form"><div class="field-group full"><label for="room-title">Headline</label><input id="room-title" required placeholder="Looking for a calm roommate near Ifite"></div><div class="field-group"><label for="room-area">Preferred area</label><input id="room-area" required placeholder="Ifite, Aroma"></div><div class="field-group"><label for="room-budget">Budget per year (₦)</label><input id="room-budget" type="number" required></div><div class="field-group"><label for="room-move">Move-in date</label><input id="room-move" type="date"></div><div class="field-group"><label for="room-looking">Looking for</label><input id="room-looking" required placeholder="Female roommate / any student"></div><div class="field-group full"><label for="room-bio">About the arrangement</label><textarea id="room-bio" required rows="5" placeholder="Share study habits, rules, and what makes a good match."></textarea></div><div class="field-group full"><div id="room-message"></div><button class="button" type="submit">Submit for review</button></div></form></section>`;$("#roommate-form").onsubmit=async e=>{e.preventDefault();try{const d=await api("/api/roommates",{method:"POST",body:JSON.stringify({title:$("#room-title").value,area:$("#room-area").value,budget:$("#room-budget").value,moveInDate:$("#room-move").value,lookingFor:$("#room-looking").value,bio:$("#room-bio").value})});$("#room-message").innerHTML=`<div class="notice success">${escapeHtml(d.message)}</div>`;e.target.reset()}catch(err){$("#room-message").innerHTML=`<div class="notice error">${escapeHtml(err.message)}</div>`}}}
async function loadData(){const [me,config,properties,products,posts,social]=await Promise.all([api("/api/me"),api("/api/config"),api("/api/properties"),api("/api/products"),api("/api/posts"),api("/api/social")]);state.me=me.user;state.config=config;state.properties=properties.properties;state.favoriteIds=properties.favoriteIds;state.products=products.products;state.posts=posts.posts;state.socialLinks=social.links||[]}
async function vendorDashboard(){if(!state.me){setRoute("/signin");return}if(!state.me.roles.includes("Vendor")&&!state.me.isAdmin){app.innerHTML=`<section class="form-shell"><div class="panel"><div class="eyebrow">Vendor workspace</div><h1>Approval comes first.</h1><p>Apply as a vendor before managing products.</p><a class="button" href="#/apply/vendor">Apply as a vendor</a></div></section>`;return}const data=await api("/api/my/products");app.innerHTML=`<section class="section-head"><div><div class="eyebrow">Vendor workspace</div><h1 style="font-size:3rem">Manage your products.</h1><p>Edit pricing, stock, delivery details, and images. Changes return to admin review.</p></div><a class="button" href="#/sell">Add product</a></section><div class="admin-list">${data.products.map(item=>`<article class="admin-row"><div><b>${escapeHtml(item.title)}</b><p>${money(item.price)} · ${escapeHtml(item.stock_status)} · ${status(item.status)}</p><p>${escapeHtml(item.description)}</p></div><div class="admin-actions"><button class="button-secondary button-small" data-edit-vendor-product="${item.id}">Edit</button></div></article>`).join("")||'<div class="empty-state">No products yet. Add your first product after vendor approval.</div>'}</div>`;$$('[data-edit-vendor-product]').forEach(button=>button.onclick=()=>{const item=data.products.find(x=>String(x.id)===button.dataset.editVendorProduct);showDialog(`<div class="eyebrow">Vendor edit</div><h2>${escapeHtml(item.title)}</h2><form id="vendor-edit" class="form-grid"><div class="field-group full"><label>Product name</label><input id="ve-title" value="${escapeHtml(item.title)}" required></div><div class="field-group"><label>Price</label><input id="ve-price" type="number" value="${item.price}" required></div><div class="field-group"><label>Stock</label><select id="ve-stock"><option value="in_stock">In stock</option><option value="low_stock">Low stock</option><option value="out_of_stock">Out of stock</option></select></div><div class="field-group full"><label>Description</label><textarea id="ve-description" rows="4" required>${escapeHtml(item.description)}</textarea></div><div class="field-group full"><label>Delivery / pickup</label><input id="ve-delivery" value="${escapeHtml(item.delivery_info||"")}"></div><div class="field-group full"><label>New images <span class="muted">(optional)</span></label><input id="ve-images" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></div><button class="button full">Save for review</button></form>`);$('#ve-stock').value=item.stock_status;$('#vendor-edit').onsubmit=async e=>{e.preventDefault();try{const images=await uploadSelectedImages($('#ve-images').files,'product');await api(`/api/my/products/${item.id}`,{method:'PATCH',body:JSON.stringify({title:$('#ve-title').value,price:$('#ve-price').value,stockStatus:$('#ve-stock').value,description:$('#ve-description').value,deliveryInfo:$('#ve-delivery').value,images})});dialog.close();showToast('Product changes sent for review.','success');vendorDashboard()}catch(err){showToast(err.message,'error')}}})}
async function connections(){if(!state.me){setRoute("/signin");return}const [requests,connections]=await Promise.all([api("/api/roommate-requests"),api("/api/roommate-connections")]);app.innerHTML=`<section class="form-header"><div class="eyebrow">Private connections</div><h1>Your roommate introductions.</h1><p>Phone numbers and email addresses stay private. Connect first, then continue the conversation safely.</p></section><section class="split-section"><div class="panel"><div class="eyebrow">Requests</div><h2>Incoming and outgoing</h2><div class="post-list">${requests.requests.map(r=>`<article class="post"><b>${escapeHtml(r.title)}</b><p>${escapeHtml(r.message)}</p><div class="meta">${r.owner_id===state.me.id?`From ${escapeHtml(r.requester_name)}`:"Sent by you"} · ${escapeHtml(r.status)}</div>${r.owner_id===state.me.id&&r.status==='new'?`<div class="card-actions"><button class="button" data-request-action="accepted" data-request-id="${r.id}">Accept</button><button class="button-secondary" data-request-action="declined" data-request-id="${r.id}">Decline</button></div>`:r.requester_id===state.me.id&&r.status==='new'?`<button class="button-quiet" data-request-action="cancelled" data-request-id="${r.id}">Cancel request</button>`:""}</article>`).join("")||'<p class="muted">No roommate requests yet.</p>'}</div></div><div class="panel soft"><div class="eyebrow">Accepted</div><h2>Private connections</h2><div class="post-list">${connections.connections.map(c=>`<article class="post"><b>${escapeHtml(c.other_name)}</b><p>Connection accepted. Use an in-site enquiry or message when messaging is enabled.</p></article>`).join("")||'<p class="muted">Accepted connections will appear here.</p>'}</div></div></section>`;$$('[data-request-action]').forEach(b=>b.onclick=async()=>{try{await api(`/api/roommate-requests/${b.dataset.requestId}`,{method:'PATCH',body:JSON.stringify({status:b.dataset.requestAction})});connections()}catch(e){showToast(e.message,'error')}})}
async function admin(){if(!state.me?.isAdmin){setRoute("/signin");showToast("Admin access is required.","error");return}await loadAdmin();const tab=state.adminTab;const tabs=[['applications','Applications'],['properties','Properties'],['products','Products'],['reviews','Reviews'],['roommates','Roommates'],['posts','News posts'],['comments','Comments']];let content='';if(tab==='reviews')content=`<div class="admin-list">${state.admin.reviews.map(r=>`<article class="admin-row"><div><b>${escapeHtml(r.property_title)}</b><p>${escapeHtml(r.reviewer_name)} · ${r.rating}/5</p><p>${escapeHtml(r.body)}</p></div><div class="admin-actions"><button class="button" data-approve-review="${r.id}">Publish</button><button class="button-secondary" data-hide-review="${r.id}">Hide</button></div></article>`).join("")||'<div class="empty-state">No property reviews to moderate.</div>'}</div>`;else if(tab==='roommates')content=`<div class="admin-list">${state.admin.roommates.map(r=>`<article class="admin-row"><div><b>${escapeHtml(r.title)}</b><p>${escapeHtml(r.user_name)} · ${escapeHtml(r.area)} · ${money(r.budget)} · ${escapeHtml(r.status)}</p><p>${escapeHtml(r.bio)}</p></div><div class="admin-actions"><button class="button" data-approve-roommate="${r.id}">Approve</button><button class="button-secondary" data-reject-roommate="${r.id}">Reject</button></div></article>`).join("")||'<div class="empty-state">No roommate profiles to review.</div>'}</div>`;else if(tab==='posts')content=`<div class="admin-list">${state.admin.posts.map(p=>`<article class="admin-row"><div><b>${escapeHtml(p.title)}</b><p>${escapeHtml(p.status)} · ${escapeHtml(p.post_type)}</p><p>${escapeHtml(p.body)}</p></div><div class="admin-actions"><button class="button-secondary" data-hide-post="${p.id}">Hide</button></div></article>`).join("")}</div>`;else if(tab==='comments')content=`<div class="admin-list">${state.admin.comments.map(c=>`<article class="admin-row"><div><b>${escapeHtml(c.post_title)}</b><p>${escapeHtml(c.author_name)} · ${escapeHtml(c.body)}</p></div><div class="admin-actions"><button class="button-secondary" data-hide-comment="${c.id}">Hide</button></div></article>`).join("")}</div>`;else if(tab==='applications')content=`<div class="admin-list">${state.admin.applications.map(a=>`<article class="admin-row"><div><b>${escapeHtml(a.role_type)} · ${escapeHtml(a.applicant_name)}</b><p>${escapeHtml(a.applicant_email)} · ${escapeHtml(a.status)}</p></div><div class="admin-actions"><button class="button" data-approve-application="${a.id}">Approve</button><button class="button-secondary" data-reject-application="${a.id}">Reject</button></div></article>`).join("")}</div>`;else {const rows=tab==='properties'?state.admin.properties:state.admin.products;content=`<div class="admin-list">${rows.map(r=>`<article class="admin-row"><div><b>${escapeHtml(r.title)}</b><p>${escapeHtml(r.status)} · ${r.published?'published':'not published'}</p><p>${escapeHtml(r.description)}</p></div><div class="admin-actions"><button class="button" data-approve-listing="${tab==='properties'?'property':'product'}:${r.id}">Approve</button><button class="button-secondary" data-edit-listing="${tab==='properties'?'property':'product'}:${r.id}">Edit</button></div></article>`).join("")}</div>`}app.innerHTML=`<section class="admin-shell"><div class="admin-head"><div><div class="eyebrow">Admin workspace</div><h1 style="font-size:3rem">Keep CampusPlug trustworthy.</h1><p>Review submissions, publish carefully, and moderate community activity.</p></div><div class="card-actions"><button class="button" id="new-admin-property">Add lodge</button><button class="button-secondary" id="new-admin-product">Add product</button></div></div><div class="admin-tabs">${tabs.map(([id,label])=>`<button class="${tab===id?'active':''}" data-admin-tab="${id}">${label}</button>`).join("")}</div>${content}</section>`;$$('[data-admin-tab]').forEach(b=>b.onclick=()=>{state.adminTab=b.dataset.adminTab;render()});bindAdminActions()}
async function profile(){if(!state.me){setRoute("/signin");return}const data=await api("/api/profile");const p=data.profile;app.innerHTML=`<section class="form-shell"><div class="form-header"><div class="eyebrow">My student profile</div><h1>Let people know who they are connecting with.</h1><p>Your email and phone remain private. Choose whether your profile details are visible to other students.</p></div><form id="profile-form" class="panel form-grid"><div class="field-group full"><label for="profile-avatar">Profile photo <span class="muted">(optional, up to 8 MB)</span></label><input id="profile-avatar" type="file" accept="image/png,image/jpeg,image/webp,image/gif">${p.avatarUrl?`<img class="profile-avatar-preview" src="${escapeHtml(p.avatarUrl)}" alt="Current profile photo">`:""}</div><div class="field-group"><label for="profile-name">Display name</label><input id="profile-name" value="${escapeHtml(p.name)}" required></div><div class="field-group"><label for="profile-department">Department / course <span class="muted">(optional)</span></label><input id="profile-department" value="${escapeHtml(p.department)}" placeholder="e.g. Computer Science"></div><div class="field-group"><label for="profile-level">Level <span class="muted">(optional)</span></label><input id="profile-level" value="${escapeHtml(p.level)}" placeholder="e.g. 300 level"></div><div class="field-group"><label for="profile-area">Preferred area <span class="muted">(optional)</span></label><input id="profile-area" value="${escapeHtml(p.preferredArea)}" placeholder="e.g. Ifite or Aroma"></div><div class="field-group full"><label for="profile-bio">Short bio <span class="muted">(optional)</span></label><textarea id="profile-bio" rows="4" maxlength="500" placeholder="A little about you, your interests, or what you are looking for on campus.">${escapeHtml(p.bio)}</textarea></div><div class="field-group full"><label for="profile-roommate">Roommate preferences <span class="muted">(optional)</span></label><textarea id="profile-roommate" rows="3" maxlength="500" placeholder="Study habits, preferred arrangement, or living expectations.">${escapeHtml(p.roommatePreferences)}</textarea></div><div class="field-group full"><label for="profile-visibility">Profile visibility</label><select id="profile-visibility"><option value="public" ${p.profileVisibility!=="private"?"selected":""}>Public to CampusPlug students</option><option value="private" ${p.profileVisibility==="private"?"selected":""}>Private except my name and avatar</option></select></div><div class="field-group full"><div id="profile-message"></div><button class="button" type="submit">Save profile</button></div></form></section>`;$("#profile-form").onsubmit=async e=>{e.preventDefault();try{const images=await uploadSelectedImages($("#profile-avatar").files,"profile");const saved=await api("/api/profile",{method:"PATCH",body:JSON.stringify({name:$("#profile-name").value,department:$("#profile-department").value,level:$("#profile-level").value,preferredArea:$("#profile-area").value,bio:$("#profile-bio").value,roommatePreferences:$("#profile-roommate").value,profileVisibility:$("#profile-visibility").value,avatarUrl:images[0]?.url})});state.me=saved.profile;$("#profile-message").innerHTML=`<div class="notice success">${escapeHtml(saved.message)}</div>`;nav()}catch(err){$("#profile-message").innerHTML=`<div class="notice error">${escapeHtml(err.message)}</div>`}}}
async function render(){shell();const current=route().split("?")[0];if(current.startsWith("/signin"))signin();else if(current==="/profile")await profile();else if(current==="/marketplace")marketplace();else if(current==="/saved")await saved();else if(current==="/tools")tools();else if(current==="/news")news();else if(current==="/social")social();else if(current==="/roommates")await roommates();else if(current==="/roommates/new")newRoommate();else if(current==="/connections")await connections();else if(current==="/vendor")await vendorDashboard();else if(current==="/admin")await admin();else if(current==="/apply/vendor")applyPage("vendor");else if(current==="/apply/landlord")applyPage("landlord");else if(current==="/sell")await sellPage();else await home();app.focus()}
window.addEventListener("hashchange",()=>render());
(async()=>{try{await loadData();if(new URLSearchParams(location.search).get("auth")==="success"){history.replaceState({},"",location.pathname+location.hash);showToast("Google sign-in complete.","success")}await render()}catch(error){app.innerHTML=`<section class="form-shell"><div class="panel"><div class="eyebrow">CampusPlug setup</div><h1>We are getting things ready.</h1><p>${escapeHtml(error.message)}</p><button class="button" onclick="location.reload()">Try again</button></div></section>`}})();
